from fastapi.middleware.cors import CORSMiddleware
import httpx
from openai import AsyncOpenAI
from anthropic import AsyncAnthropic
import google.generativeai as genai

app = FastAPI()
app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_credentials=True, allow_methods=["*"], allow_headers=["*"])

OPENAI_API_KEY = os.getenv("OPENAI_API_KEY")
ANTHROPIC_API_KEY = os.getenv("ANTHROPIC_API_KEY")
XAI_API_KEY = os.getenv("XAI_API_KEY")
GOOGLE_API_KEY = os.getenv("GOOGLE_API_KEY")
CEREBRAS_API_KEY = os.getenv("CEREBRAS_API_KEY")
EXA_API_KEY = os.getenv("EXA_API_KEY")

if not EXA_API_KEY:
    raise RuntimeError("EXA_API_KEY required")
openai_client = AsyncOpenAI(api_key=OPENAI_API_KEY) if OPENAI_API_KEY else None
anthropic_client = AsyncAnthropic(api_key=ANTHROPIC_API_KEY) if ANTHROPIC_API_KEY else None
if GOOGLE_API_KEY:
    genai.configure(api_key=GOOGLE_API_KEY)
research_sessions: Dict[str, Dict] = {}
uploaded_files: Dict[str, Dict] = {}

class ExaSearchClient:
    def __init__(self, api_key: str):
        self.api_key = api_key
        self.base_url = ""
    async def intelligent_search(self, query: str, num_results: int = 250) -> List[Dict]:
        searches = [
            {"query": query, "type": "auto"},
            {"query": f"academic research {query}", "type": "keyword"},
            {"query": f"expert analysis {query}", "type": "neural"},
            {"query": f"latest articles {query}", "type": "auto"},
            {"query": f"review {query}", "type": "keyword"},
        ]
        all_results = []
        async with httpx.AsyncClient(timeout=120.0) as client:
            per = max(1, num_results // len(searches))
            for conf in searches:
                try:
                    r = await client.post(
                        f"{self.base_url}/search",
                        headers={
                            "x-api-key": self.api_key,
                            "Content-Type": "application/json"
                        },
                        json={
                            **conf,
                            "num_results": per,
                            "use_autoprompt": True,
                            "contents": {
                                "text": {"max_characters": 9000}
                            },
                        }
                    )
                    if r.status_code == 200:
                        all_results.extend(r.json().get("results", []))
                except Exception:
                    continue
        return all_results

class CerebrasClient:
    def __init__(self, api_key: str):
        self.api_key = api_key
        self.base_url = ""
    async def chat_completion(self, model: str, messages: List[Dict], max_tokens: int = 6000):
        async with httpx.AsyncClient(timeout=120.0) as client:
            response = await client.post(
                f"{self.base_url}/chat/completions",
                headers={
                    "Authorization": f"Bearer {self.api_key}",
                    "Content-Type": "application/json"
                },
                json={
                    "model": model,
                    "messages": messages,
                    "max_tokens": max_tokens,
                    "stream": False
                }
            )
            response.raise_for_status()
            return response.json()

class AdvancedOrchestrator:
    def __init__(self, session_id: str):
        self.session_id = session_id
        self.state = { "sources": [], "analyses": [], "report": "", "confidence": 0.0}
        research_sessions[session_id] = self.state
        self.exa = ExaSearchClient(EXA_API_KEY)
        self.cerebras = CerebrasClient(CEREBRAS_API_KEY) if CEREBRAS_API_KEY else None
    async def run(self, query: str, file_ids: List[str]) -> AsyncGenerator[str, None]:
        yield self._emit("status", {"step": "search", "message": "Web research (250+ sources)"})
        sources = await self._exa_research(query)
        self.state["sources"] = sources
        yield self._emit("sources", {"count": len(sources)})
        yield self._emit("status", {"step": "analysis", "message": "Multi-LLM mass analysis"})
        result = await self._parallel_analysis(query, sources, file_ids)
        analyses, perspectives = result["analyses"], result["perspectives"]
        self.state["analyses"] = analyses
        yield self._emit("analysis", {"perspectives": list(perspectives.keys())})
        yield self._emit("status", {"step": "synthesis", "message": "Synthesizing final expert-grade report"})
        async for chunk in self._stream_report(query, analyses, sources, perspectives):
            yield chunk
        yield self._emit("complete", {"sources": len(sources), "confidence": self.state["confidence"]})

    async def _exa_research(self, query: str) -> List[Dict]:
        rs = await self.exa.intelligent_search(query, num_results=250)
        seen = set()
        unique = []
        for r in sorted(rs, key=lambda x: x.get("score", 0), reverse=True):
            u = r.get("url")
            if u and u not in seen:
                seen.add(u)
                unique.append({
                    "title": r.get("title", ""),
                    "url": u,
                    "text": r.get("text", ""),
                    "score": r.get("score", 0),
                    "published": r.get("published_date", ""),
                    "author": r.get("author","")
                })
        return unique

    async def _parallel_analysis(self, query: str, sources: List[Dict], file_ids: List[str]):
        files_text = ""
        if file_ids:
            for fid in file_ids:
                if fid in uploaded_files:
                    files_text += uploaded_files[fid]["content"][:2000]
        sources_text = "\n\n".join([f"[{i+1}] {s['title']} {s['text'][:500]}" for i,s in enumerate(sources[:60])])
        prompt = f"Empirically analyze these {len(sources)} sources about: {query}. Files: {files_text}\n{sources_text}\nReturn a JSON with main_findings, insights, contradictions, evidence. 250+ sources must be used precisely."
        perspectives = {}
        tasks = []
        if openai_client and OPENAI_API_KEY:
            tasks.append(self._analysis_openai(prompt))
        if anthropic_client and ANTHROPIC_API_KEY:
            tasks.append(self._analysis_anthropic(prompt))
        if self.cerebras and CEREBRAS_API_KEY:
            tasks.append(self._analysis_cerebras(prompt, "llama-3.3-120b"))
            tasks.append(self._analysis_cerebras(prompt, "qwen3-235b-thinking"))
        if GOOGLE_API_KEY:
            tasks.append(self._analysis_gemini(prompt))
        if XAI_API_KEY:
            tasks.append(self._analysis_grok(prompt))
        results = await asyncio.gather(*tasks)
        for i, p in enumerate(["GPT-5", "Claude 4.5", "Llama 120B", "Qwen 235B", "Gemini 2.5 Pro", "Grok-4"]):
            if i < len(results) and results[i]:
                perspectives[p] = results[i]
        return {"analyses": results, "perspectives": perspectives}

    async def _analysis_openai(self, prompt):
        res = await openai_client.chat.completions.create(
            model="gpt-5",
            messages=[{"role": "user", "content": prompt}],
            temperature=0.3, max_tokens=4000)
        return res.choices[0].message.content
    async def _analysis_anthropic(self, prompt):
        res = await anthropic_client.messages.create(
            model="claude-sonnet-4-5-20250928",
            max_tokens=4000,
            temperature=0.3,
            messages=[{"role": "user", "content": prompt}])
        return res.content[0].text
    async def _analysis_cerebras(self, prompt, model):
        result = await self.cerebras.chat_completion(model, [{"role": "user", "content": prompt}], max_tokens=4000)
        return result["choices"][0]["message"]["content"]
    async def _analysis_grok(self, prompt):
        async with httpx.AsyncClient(timeout=120.0) as client:
            r = await client.post(
                "",
                headers={"Authorization": f"Bearer {XAI_API_KEY}","Content-Type":"application/json"},
                json={"model": "grok-4-fast","messages":[{"role":"user","content":prompt}],"max_tokens":4000})
            r.raise_for_status()
            return r.json()["choices"][0]["message"]["content"]
    async def _analysis_gemini(self, prompt):
        model = genai.GenerativeModel("gemini-2.5-pro-preview")
        res = await asyncio.to_thread(model.generate_content, prompt)
        return res.text

    async def _stream_report(self, query: str, analyses, sources, perspectives) -> AsyncGenerator[str, None]:
        sources_list = "\n".join([f"[{i+1}] {s['title']} - {s['url']}" for i,s in enumerate(sources[:250])])
        perspectives_txt = "\n\n".join([f"## {k}\n{v}" for k, v in perspectives.items()])
        prompt = (
            f"Write a 50-page, expert-level research report on: {query}\n"
            "All data, findings, and arguments must be cited using only the given 250+ sources. "
            f"\n\nSources:\n{sources_list}\n\nAnalyses:\n{perspectives_txt}\n"
            "Structure: Executive Summary (2p), Research Plan, 3 Research Questions sections, Empirical Data (+tables), "
            "Critical Debate, Contradictions/Uncertainties, Recommendations, Conclusion, Full Reference List."
            "\nUse rigorous, professional academic formatting in Markdown. Use [1],[2] etc for all citations."
            "\nLanguage: Hungarian. Word count: 20,000+ words. No hallucinations. All statements must be justified by source content."
        )
        parts = []
        if anthropic_client and ANTHROPIC_API_KEY:
            async with anthropic_client.messages.stream(
                model="claude-sonnet-4-5-20250928",
                max_tokens=64000,
                temperature=0.7,
                messages=[{"role": "user", "content": prompt}]
            ) as stream:
                async for t in stream.text_stream:
                    parts.append(t)
                    yield self._emit("report_chunk", {"content": t})
        elif openai_client and OPENAI_API_KEY:
            stream = await openai_client.chat.completions.create(
                model="gpt-5",
                messages=[{"role": "user", "content": prompt}],
                stream=True, max_tokens=64000)
            async for chunk in stream:
                if chunk.choices[0].delta.content:
                    txt = chunk.choices[0].delta.content
                    parts.append(txt)
                    yield self._emit("report_chunk", {"content": txt})
        self.state["report"] = "".join(parts)
        self.state["confidence"] = 0.92

    def _emit(self, typ, data):
        return json.dumps({"type": typ, **data}) + "\n"

@app.get("/", response_class=HTMLResponse)
async def root():
    with open("index.html","r",encoding="utf-8") as f: return f.read()

@app.post("/api/upload")
async def upload_file(file: UploadFile = File(...)):
    max_size = 50 * 1024 * 1024
    content = await file.read()
    if len(content) > max_size:
        raise HTTPException(413, "File too large")
    try:
        txt = content.decode("utf-8")
    except:
        txt = content.decode("latin-1", errors="ignore")
    fid = hashlib.sha256(f"{file.filename}_{time.time()}".encode()).hexdigest()[:16]
    uploaded_files[fid] = {"id": fid, "filename": file.filename, "content": txt, "size": len(content), "uploaded_at": datetime.now().isoformat()}
    return {"success": True, "file_id": fid, "filename": file.filename, "size": len(content)}

@app.get("/api/research")
async def research(query: str, file_ids: str = ""):
    if not query: raise HTTPException(400, "Query required")
    session_id = hashlib.sha256(f"{query}_{time.time()}".encode()).hexdigest()[:16]
    orchestrator = AdvancedOrchestrator(session_id)
    file_id_list = [fid.strip() for fid in file_ids.split(",") if fid.strip()]
    async def generate():
        async for chunk in orchestrator.run(query, file_id_list): yield chunk
    return StreamingResponse(generate(), media_type="application/x-ndjson")

@app.get("/api/health")
